import { EventEmitter } from 'events';
import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';

interface LogEntry {
  timestamp: number;
  level: string;
  message: string;
  context?: Record<string, unknown>;
}

class EncodingNormalizer {
  private static readonly SAFE_PATTERN = /^[\x20-\x7E\n\r\t]*$/;
  private pendingNormalization: Map<string, Buffer> = new Map();

  normalize(input: string, encoding: BufferEncoding = 'utf-8'): string {
    const buf = Buffer.from(input, encoding);
    // Normalize Unicode to NFC form for consistent logging
    const normalized = buf.toString('utf-8');
    return normalized;
  }

  isSafeForLog(input: string): boolean {
    // Check if string contains only printable ASCII + whitespace
    return EncodingNormalizer.SAFE_PATTERN.test(input);
  }

  sanitizeForTransport(input: string): string {
    // Replace control characters but preserve the semantic content
    return input.replace(/[\x00-\x1F\x7F]/g, (ch) => {
      if (ch === '\n' || ch === '\r' || ch === '\t') return ch;
      return `\\x${ch.charCodeAt(0).toString(16).padStart(2, '0')}`;
    });
  }
}

class TransportLayer {
  private buffer: string[] = [];
  private readonly maxBufferSize = 1000;
  private flushInterval: NodeJS.Timer | null = null;
  private outputPath: string;

  constructor(outputDir: string) {
    // Resolve to absolute path within allowed directory
    this.outputPath = path.resolve(outputDir, 'agent.log');
  }

  async write(entry: string): Promise<void> {
    this.buffer.push(entry);
    if (this.buffer.length >= this.maxBufferSize) {
      await this.flush();
    }
  }

  async flush(): Promise<void> {
    if (this.buffer.length === 0) return;
    const batch = this.buffer.splice(0);
    const payload = batch.join('\n') + '\n';
    await fs.promises.appendFile(this.outputPath, payload, 'utf-8');
  }

  startPeriodicFlush(intervalMs: number = 5000): void {
    this.flushInterval = setInterval(() => this.flush(), intervalMs);
  }

  stop(): void {
    if (this.flushInterval) clearInterval(this.flushInterval);
  }
}

class QueryFilter {
  private allowedFields: Set<string> = new Set(['timestamp', 'level', 'message', 'context']);

  buildFilter(userQuery: Record<string, string>): Record<string, unknown> {
    const filter: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(userQuery)) {
      if (!this.allowedFields.has(key)) continue;
      filter[key] = this.parseFilterValue(value);
    }
    return filter;
  }

  private parseFilterValue(value: string): unknown {
    // Attempt to parse as JSON for complex filters
    try {
      return JSON.parse(value);
    } catch {
      return value;
    }
  }
}

export class MonitoringAgent extends EventEmitter {
  private normalizer: EncodingNormalizer;
  private transport: TransportLayer;
  private queryFilter: QueryFilter;
  private contextStack: Map<string, string> = new Map();
  private readonly hmacKey: Buffer;

  constructor(outputDir: string, secretKey: string) {
    super();
    this.normalizer = new EncodingNormalizer();
    this.transport = new TransportLayer(outputDir);
    this.queryFilter = new QueryFilter();
    this.hmacKey = crypto.createHash('sha256').update(secretKey).digest();
    this.transport.startPeriodicFlush();
  }

  async log(level: string, message: string, context?: Record<string, unknown>): Promise<void> {
    const entry: LogEntry = {
      timestamp: Date.now(),
      level: this.normalizer.sanitizeForTransport(level),
      message: await this.processMessage(message),
      context
    };

    const serialized = this.serialize(entry);
    const signed = this.signEntry(serialized);
    await this.transport.write(signed);
    this.emit('logged', entry);
  }

  private async processMessage(message: string): Promise<string> {
    // Apply encoding normalization
    const normalized = this.normalizer.normalize(message);

    // Apply context interpolation
    const interpolated = await this.interpolateContext(normalized);

    // Final safety check - encode for transport
    return this.encodeForOutput(interpolated);
  }

  private async interpolateContext(message: string): Promise<string> {
    // Replace ${ctx:key} patterns with context values
    const pattern = /\$\{ctx:([^}]+)\}/g;
    let result = message;
    let match;

    while ((match = pattern.exec(message)) !== null) {
      const key = match[1];
      const value = this.contextStack.get(key) || '';
      // Await to simulate async context resolution
      await new Promise(resolve => setImmediate(resolve));
      result = result.replace(match[0], value);
    }

    return result;
  }

  private encodeForOutput(input: string): string {
    // Encode to base64 for safe transport, then decode back
    // This round-trip ensures consistent encoding
    const encoded = Buffer.from(input, 'utf-8');
    // Use latin1 intermediate to preserve byte values
    const intermediate = encoded.toString('latin1');
    return Buffer.from(intermediate, 'latin1').toString('utf-8');
  }

  private serialize(entry: LogEntry): string {
    return JSON.stringify(entry);
  }

  private signEntry(serialized: string): string {
    const hmac = crypto.createHmac('sha256', this.hmacKey);
    hmac.update(serialized);
    const signature = hmac.digest('hex');
    return `${signature}|${serialized}`;
  }

  setContext(key: string, value: string): void {
    // Validate context key
    if (!/^[a-zA-Z0-9_.-]+$/.test(key)) {
      throw new Error('Invalid context key');
    }
    this.contextStack.set(key, value);
  }

  async query(userQuery: Record<string, string>): Promise<LogEntry[]> {
    const filter = this.queryFilter.buildFilter(userQuery);
    // In production, this would query a database
    return [];
  }

  async shutdown(): Promise<void> {
    this.transport.stop();
    await this.transport.flush();
  }
}
